import{_ as t,o as i,c as a,ah as o}from"./chunks/framework.Sdx4l2LO.js";const u=JSON.parse('{"title":"ADR-013: Duplicate Instance Detection & Win32 Mutex Bypass","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-013-duplicate-instance-detection-bypass.md","filePath":"adr/ADR-013-duplicate-instance-detection-bypass.md","lastUpdated":1774803703000}'),s={name:"adr/ADR-013-duplicate-instance-detection-bypass.md"};function n(l,e,r,c,p,d){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-013-duplicate-instance-detection-win32-mutex-bypass" tabindex="-1">ADR-013: Duplicate Instance Detection &amp; Win32 Mutex Bypass <a class="header-anchor" href="#adr-013-duplicate-instance-detection-win32-mutex-bypass" aria-label="Permalink to &quot;ADR-013: Duplicate Instance Detection &amp; Win32 Mutex Bypass&quot;">​</a></h1><p><strong>Status</strong>: Proposed <strong>Date</strong>: 2026-03-24 <strong>Deciders</strong>: kooshapari, DINOForge agents</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Diplomacy is Not an Option (DINO), like many Steam games, enforces a single-instance constraint via Win32 named mutexes. This prevents multiple game clients from running simultaneously and avoids player confusion, save file corruption, and port conflicts.</p><h3 id="current-problem" tabindex="-1">Current Problem <a class="header-anchor" href="#current-problem" aria-label="Permalink to &quot;Current Problem&quot;">​</a></h3><p>When DINOForge (<code>launch-game</code> command) or test harnesses attempt to launch the game repeatedly, they encounter a fatal error:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Another instance is already running. Only one instance of the game is allowed.</span></span></code></pre></div><p>This occurs because:</p><ol><li><p><strong>Steam maintains a mutex</strong> — Steam holds a named mutex while the game is running (likely <code>Global\\Valve_SteamMutex_*</code> or a game-specific equivalent).</p></li><li><p><strong>Previous instances may not fully release the mutex</strong> — Even after:</p><ul><li>User manually kills the game process (<code>Stop-Process</code>)</li><li>OS forcibly terminates the process</li><li>Game crashes or exits abnormally</li></ul><p>The mutex handle may still be held in the kernel&#39;s mutex table, preventing a new instance from acquiring it.</p></li><li><p><strong>Direct exe launch still respects the mutex</strong> — Even if we bypass Steam&#39;s launcher and call the <code>.exe</code> directly with <code>-bepinex</code>, the game&#39;s own init code (likely in <code>Diplomacy is Not an Option.exe</code>&#39;s static initializer or <code>Unity.Player.dll</code>) calls <code>CreateMutex</code> and checks if it already exists. If it does, the game exits with the &quot;another instance&quot; error and never reaches BepInEx bootstrap.</p></li></ol><h3 id="how-dino-detects-duplicate-instances" tabindex="-1">How DINO Detects Duplicate Instances <a class="header-anchor" href="#how-dino-detects-duplicate-instances" aria-label="Permalink to &quot;How DINO Detects Duplicate Instances&quot;">​</a></h3><p>DINO&#39;s detection mechanism is likely one of:</p><ul><li><strong>Named mutex</strong> — Windows API <code>CreateMutex(mutexName)</code> check in game init code or Unity player startup</li><li><strong>TCP port lock</strong> — Game tries to bind to a port; if it fails, another instance is assumed</li><li><strong>File lock</strong> — Temp file in <code>%LOCALAPPDATA%</code> or <code>%TEMP%</code> that the game exclusively locks</li></ul><p>Most Steam games use named mutexes. The mutex is created at game startup in a global namespace accessible to all processes on the system.</p><h3 id="current-workaround-limitations" tabindex="-1">Current Workaround Limitations <a class="header-anchor" href="#current-workaround-limitations" aria-label="Permalink to &quot;Current Workaround Limitations&quot;">​</a></h3><p>The <code>launch-game.md</code> command currently:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Stop-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Diplomacy is Not an Option&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ErrorAction SilentlyContinue</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Sleep</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Seconds </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FilePath </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...\\Diplomacy is Not an Option.exe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...</span></span></code></pre></div><p><strong>Why this fails</strong>: The OS may not immediately release kernel mutexes held by a killed process. Even after <code>Stop-Process</code> and a sleep, the mutex may still exist in the kernel&#39;s mutex table, and the new instance fails to acquire it.</p><h3 id="investigation-needed" tabindex="-1">Investigation Needed <a class="header-anchor" href="#investigation-needed" aria-label="Permalink to &quot;Investigation Needed&quot;">​</a></h3><p>Before committing to a solution, we must determine:</p><ol><li><p><strong>What is the exact mutex name?</strong></p><ul><li>Is it <code>Global\\Valve_SteamMutex_*</code>?</li><li>Is it game-specific, e.g., <code>Global\\DiplomaIsNotAnOption_*</code>?</li><li>How to enumerate all named mutexes on the system to find it?</li></ul></li><li><p><strong>Can we release it programmatically?</strong></p><ul><li>Win32 API <code>OpenMutex</code> + <code>ReleaseMutex</code> in PowerShell (via P/Invoke)?</li><li>Does the kernel allow non-owning processes to release mutexes, or does it validate ownership?</li></ul></li><li><p><strong>Is it a file lock instead?</strong></p><ul><li>Where is the lock file? (<code>%TEMP%</code>, <code>%LOCALAPPDATA%</code>, <code>BepInEx/</code>, game root?)</li><li>Can we simply delete it?</li></ul></li><li><p><strong>Does the mutex have a timeout or auto-cleanup?</strong></p><ul><li>Some games release the mutex after a grace period (e.g., 10 seconds) if no heartbeat is detected</li><li>If so, we might just need a longer sleep</li></ul></li><li><p><strong>Will bypassing the mutex cause gameplay issues?</strong></p><ul><li>Could two game instances interfere with each other if both acquire the mutex?</li><li>Do they share configuration, save files, or other resources that would corrupt?</li></ul></li></ol><h2 id="decision-options" tabindex="-1">Decision Options <a class="header-anchor" href="#decision-options" aria-label="Permalink to &quot;Decision Options&quot;">​</a></h2><h3 id="option-1-direct-win32-mutex-release-powershell-p-invoke" tabindex="-1">Option 1: Direct Win32 Mutex Release (PowerShell P/Invoke) <a class="header-anchor" href="#option-1-direct-win32-mutex-release-powershell-p-invoke" aria-label="Permalink to &quot;Option 1: Direct Win32 Mutex Release (PowerShell P/Invoke)&quot;">​</a></h3><p><strong>How it works:</strong></p><ol><li>Enumerate all named mutexes via Win32 API <code>CreateToolhelp32Snapshot</code> or <code>NtQuerySystemInformation</code></li><li>Find the DINO/Steam mutex by name pattern</li><li>Open it with <code>OpenMutex</code> from a PowerShell script</li><li>Call <code>ReleaseMutex</code> to force-release</li><li>Attempt game launch</li></ol><p><strong>Pros:</strong></p><ul><li>Minimal dependencies (pure Win32 P/Invoke)</li><li>Works offline, no external tools needed</li><li>Can be packaged in PowerShell directly</li></ul><p><strong>Cons:</strong></p><ul><li>Kernel may reject non-owning process trying to release a mutex</li><li>Enumerating named mutexes is non-trivial (not exposed in standard .NET)</li><li>Requires understanding Windows kernel mutex ownership semantics</li><li>May require admin privileges</li></ul><h3 id="option-2-use-steam-s-applaunch-with-single-instance-override-flags" tabindex="-1">Option 2: Use Steam&#39;s <code>-applaunch</code> with Single-Instance Override Flags <a class="header-anchor" href="#option-2-use-steam-s-applaunch-with-single-instance-override-flags" aria-label="Permalink to &quot;Option 2: Use Steam&#39;s `-applaunch` with Single-Instance Override Flags&quot;">​</a></h3><p><strong>How it works:</strong></p><ol><li>Call <code>steam://run/411400 -single_instance</code> (if flag exists) or similar</li><li>Steam may have a known flag to force bypass instance checking</li><li>If not, submit to Valve support to confirm no such flag exists</li></ol><p><strong>Pros:</strong></p><ul><li>Avoids mutexes entirely if Steam has a documented override</li><li>Delegates to Steam&#39;s own multi-instance handling</li></ul><p><strong>Cons:</strong></p><ul><li>May not exist or may be undocumented</li><li>Requires Steam to be running</li><li>Slower than direct exe launch</li></ul><h3 id="option-3-rename-copy-exe-to-bypass-steam-association" tabindex="-1">Option 3: Rename/Copy Exe to Bypass Steam Association <a class="header-anchor" href="#option-3-rename-copy-exe-to-bypass-steam-association" aria-label="Permalink to &quot;Option 3: Rename/Copy Exe to Bypass Steam Association&quot;">​</a></h3><p><strong>How it works:</strong></p><ol><li>Copy <code>Diplomacy is Not an Option.exe</code> to <code>DINO_Launcher_Temp.exe</code></li><li>Launch the copy instead</li><li>Copy has a different process name, potentially different mutex name</li><li>On exit, delete the copy</li></ol><p><strong>Pros:</strong></p><ul><li>No P/Invoke needed</li><li>Bypasses Steam&#39;s launcher entirely</li></ul><p><strong>Cons:</strong></p><ul><li>Game may detect copy via file path or signature and reject it</li><li>Creates temp files that could accumulate</li><li>Fragile; depends on game not validating exe integrity</li></ul><h3 id="option-4-temporarily-kill-steam-process-nuclear-option" tabindex="-1">Option 4: Temporarily Kill Steam Process (Nuclear Option) <a class="header-anchor" href="#option-4-temporarily-kill-steam-process-nuclear-option" aria-label="Permalink to &quot;Option 4: Temporarily Kill Steam Process (Nuclear Option)&quot;">​</a></h3><p><strong>How it works:</strong></p><ol><li>Kill <code>steam.exe</code> (force via <code>taskkill /F</code>)</li><li>Wait for kernel to release all Steam-held mutexes</li><li>Launch game directly</li><li>Optionally restart Steam after game closes</li></ol><p><strong>Pros:</strong></p><ul><li>Guaranteed to release any Steam mutex</li></ul><p><strong>Cons:</strong></p><ul><li>Kills the Steam client, losing overlay, achievements, etc.</li><li>Intrusive and hostile to user&#39;s session</li><li>May interfere with other Steam games or Steam features</li></ul><h3 id="option-5-increase-sleep-duration-empirical-brute-force" tabindex="-1">Option 5: Increase Sleep Duration (Empirical Brute Force) <a class="header-anchor" href="#option-5-increase-sleep-duration-empirical-brute-force" aria-label="Permalink to &quot;Option 5: Increase Sleep Duration (Empirical Brute Force)&quot;">​</a></h3><p><strong>How it works:</strong></p><ol><li><code>Stop-Process</code></li><li>Sleep for 10-30 seconds instead of 3</li><li>Retry launch</li><li>If still fails, repeat with longer sleep</li></ol><p><strong>Pros:</strong></p><ul><li>Zero code changes</li><li>No P/Invoke or dependencies</li></ul><p><strong>Cons:</strong></p><ul><li>Slow and unreliable</li><li>Kernel may never release the mutex on some systems</li><li>Doesn&#39;t scale (what if mutex is held indefinitely?)</li></ul><h2 id="recommended-decision" tabindex="-1">Recommended Decision <a class="header-anchor" href="#recommended-decision" aria-label="Permalink to &quot;Recommended Decision&quot;">​</a></h2><p><strong>Hybrid approach: Option 1 + Option 5 (with fallback to Option 3)</strong></p><h3 id="implementation-strategy" tabindex="-1">Implementation Strategy <a class="header-anchor" href="#implementation-strategy" aria-label="Permalink to &quot;Implementation Strategy&quot;">​</a></h3><ol><li><p><strong>First attempt (safest):</strong></p><ul><li>Kill game process</li><li>Sleep 3 seconds</li><li>Attempt mutex release via P/Invoke (with graceful failure if not possible)</li><li>Sleep 2 more seconds</li><li>Launch game</li></ul></li><li><p><strong>If that fails, escalate to Option 5:</strong></p><ul><li>Increase sleep to 10 seconds</li><li>Retry launch</li></ul></li><li><p><strong>Last resort (if both fail):</strong></p><ul><li>Warn user, then proceed with Option 3 (copy exe)</li></ul></li></ol><h3 id="why-this-approach" tabindex="-1">Why This Approach <a class="header-anchor" href="#why-this-approach" aria-label="Permalink to &quot;Why This Approach&quot;">​</a></h3><ul><li><strong>Prioritizes correctness</strong> — Direct mutex release is the most robust if it works</li><li><strong>Has graceful fallbacks</strong> — Doesn&#39;t fail catastrophically if P/Invoke fails</li><li><strong>Empirically proven</strong> — Sleep-based approach is known to work on some systems</li><li><strong>Minimal friction</strong> — Doesn&#39;t kill Steam or rename exes unless absolutely necessary</li><li><strong>Testable</strong> — Each step can be verified independently</li></ul><h3 id="investigation-phase" tabindex="-1">Investigation Phase <a class="header-anchor" href="#investigation-phase" aria-label="Permalink to &quot;Investigation Phase&quot;">​</a></h3><p>Before writing code, conduct:</p><ol><li><strong>Mutex name discovery</strong> — Use Sysinternals <code>Handle.exe</code> or PowerShell WMI to enumerate mutexes and find the exact name</li><li><strong>P/Invoke proof-of-concept</strong> — Write a small PowerShell script to test <code>OpenMutex</code> + <code>ReleaseMutex</code> on the discovered name</li><li><strong>Ownership validation</strong> — Test whether a non-owning process can release the mutex (it likely can&#39;t; this determines if Option 1 is viable)</li><li><strong>Kernel behavior study</strong> — Measure how long the kernel holds a mutex after the owning process dies on this system</li><li><strong>Test on real game</strong> — Verify mutex name doesn&#39;t change between game versions or configurations</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="if-option-1-works-mutex-release" tabindex="-1">If Option 1 Works (Mutex Release) <a class="header-anchor" href="#if-option-1-works-mutex-release" aria-label="Permalink to &quot;If Option 1 Works (Mutex Release)&quot;">​</a></h3><ul><li><code>launch-game</code> becomes highly reliable</li><li>No dependency on timing or race conditions</li><li>Enables fully automated testing workflows</li><li>Establishes pattern for other Win32 issues (if they arise)</li></ul><h3 id="if-option-1-doesn-t-work-kernel-ownership" tabindex="-1">If Option 1 Doesn&#39;t Work (Kernel Ownership) <a class="header-anchor" href="#if-option-1-doesn-t-work-kernel-ownership" aria-label="Permalink to &quot;If Option 1 Doesn&#39;t Work (Kernel Ownership)&quot;">​</a></h3><ul><li>Must fall back to Option 5 (sleep) or Option 3 (copy exe)</li><li>Sleep adds latency to test workflows (acceptable if &lt; 15 seconds)</li><li>Copy-exe approach is fragile but functional as last resort</li></ul><h3 id="long-term" tabindex="-1">Long-Term <a class="header-anchor" href="#long-term" aria-label="Permalink to &quot;Long-Term&quot;">​</a></h3><ul><li>Document the mutex name and workaround in <code>docs/troubleshooting.md</code></li><li>Add <code>--force-launch</code> flag to <code>launch-game</code> that skips mutex check entirely</li><li>Consider wrapping this into a standalone <code>release-game-mutex</code> PowerShell function for manual use</li><li>If Steam provides an official workaround, update this ADR and switch to it</li></ul><h2 id="links-to-investigation" tabindex="-1">Links to Investigation <a class="header-anchor" href="#links-to-investigation" aria-label="Permalink to &quot;Links to Investigation&quot;">​</a></h2><ul><li>Windows named mutexes: <a href="https://docs.microsoft.com/en-us/windows/win32/sync/named-mutexes" target="_blank" rel="noreferrer">https://docs.microsoft.com/en-us/windows/win32/sync/named-mutexes</a></li><li>Sysinternals Handle.exe: <a href="https://docs.microsoft.com/en-us/sysinternals/downloads/handle" target="_blank" rel="noreferrer">https://docs.microsoft.com/en-us/sysinternals/downloads/handle</a></li><li>PowerShell P/Invoke patterns: <a href="https://github.com/powershell/psl-teamcity/" target="_blank" rel="noreferrer">https://github.com/powershell/psl-teamcity/</a></li></ul>',74)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
